/* RasterTrace browser WASM pinned from bradsec/rastertrace blob 5c79c5cd9224f7521dd04e998ebfe66ba75fcf7b.
 * Included as Base64 in this experiment because the current connected
 * GitHub Contents writer only accepts UTF-8 text files. Replace with an
 * ordinary .wasm binary in a later bundler-based build.
 */
const wasmB64="";
export function browserVtracerWasm(){
 const bytes=atob(wasmB64),buffer=new Uint8Array(bytes.length);
 for(let i=0;i<bytes.length;i++)buffer[i]=bytes.charCodeAt(i);
 return buffer.buffer;
}
